"""v76 stage C - timekeeping and instrument collections: watches, clocks, scientific instruments, cameras, typewriters, radios and early electronics, telephones, musical instruments.
One engine, eight data blocks. Each collection: type, material, feature, colour, era, condition, marks (invented names in quotes), display, look, prompt, group prompt, fill versions."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from famlib import P, slug
COND = P("in mint condition with its original box; lightly used with a soft patina; worn bright on every edge; scratched and dull; stained with age spots; missing a small part; cracked and repaired with glue; rusted in places; freshly restored to a high shine; dusty from years in an attic; heavily played with and dented; covered in the marks of a workshop")
DISPLAY = P("in a glass-topped display case; on a velvet tray; in a felt-lined drawer; on a shelf among other pieces; in a wooden box with a hinged lid; on a stand under a lamp; in a museum cabinet with a typed label; on a workbench with tools beside it; in a shop window; on a market stall table; in a collector's cabinet with many small drawers")
SERVICE = P("a repair tag tied on with string; a scratched owner's initials; a handwritten price label; a repairer's stamp inside; a dated inscription; a faded paper label; a worn serial number; a museum accession number in white ink")
COLOUR = P("black; ivory; cream; walnut brown; deep red; forest green; navy blue; brushed silver; polished brass; gold; turquoise; pale grey; mustard yellow; two-tone black and chrome")
GROUP = P("a single piece; a matched pair; a set of three; a row of four different pieces; a tray of six; a full grid of nine")
# name|types|materials|features|eras|markkinds
C = {
 'watch': ('watch', "an open-face pocket watch; a hunter-case pocket watch with a hinged lid; a railway pocket watch; a dress wristwatch; a diver's wristwatch; a pilot's wristwatch; a chronograph wristwatch; a military field watch; a digital LCD wristwatch; a ladies' cocktail watch; a skeleton watch with the movement visible; a pendant fob watch; a calendar wristwatch; a quartz fashion watch",
  "gold-filled metal; stainless steel; sterling silver; brass; rose gold; chrome-plated metal; titanium; plastic resin", "an enamel dial with Roman numerals; luminous hands and markers; a sub-seconds dial; a date window; a tachymeter bezel; a black dial with white baton markers; a mother-of-pearl dial; a cracked crystal; a leather strap; a steel bracelet; a woven fabric strap; a gold chain",
  "from the 1920s; from the 1940s; from the 1960s; from the 1970s; from the 1980s; from the 2000s; from the 2010s; of a current design", ("dial", "case back")),
 'clock': ('clock', "a wooden mantel clock; a tall longcase clock; a brass carriage clock; a cuckoo clock; a wall regulator clock; a twin-bell alarm clock; a kitchen wall clock; a school wall clock; a railway station clock; a skeleton clock under a glass dome; an Art Deco electric clock; a flip-number digital clock; a lantern clock; a sunburst wall clock; a travel clock in a folding case",
  "polished mahogany; carved oak; brass and glass; bakelite; painted tin; white porcelain; chrome and enamel; plastic", "a white enamel dial with black numerals; a painted moon dial; a pendulum visible behind glass; chiming bells; a cuckoo door; a hinged back door; a brass key in the winder; a second hand sweeping; a luminous dial; a mirrored backing",
  "from the 1800s; from the 1900s; from the 1930s; from the 1950s; from the 1970s; from the 1980s; of a current design", ("dial", "pendulum plate")),
 'instrument': ('scientific instrument', "a brass microscope in a case; a brass telescope on a tripod; a ship's sextant; an astrolabe; an aneroid barometer; a surveyor's theodolite; an orrery; a table globe; an apothecary balance scale; a galvanometer; an oscilloscope; a slide rule; an armillary sphere; a garden sundial; a pocket compass; a spectroscope; a mechanical calculator; a Geiger counter",
  "lacquered brass; polished steel; mahogany and brass; glass and nickel; painted iron; bakelite; walnut and ivorine; chrome and glass", "an engraved scale in tiny numbers; a fitted wooden case lined with velvet; a focusing knob; a vernier scale; a mirror and lens; a hinged lid with a label; a dial with a thin needle; glass tubes; a rotating arm",
  "from the 1700s; from the 1800s; from the 1900s; from the 1930s; from the 1950s; from the 1970s", ("maker plate", "scale")),
 'camera': ('camera', "a leatherette box camera; a folding bellows camera; a twin-lens reflex camera; a rangefinder camera; a 35mm single-lens reflex camera; an instant-print camera; a wooden view camera with a dark cloth; a press camera with a flash gun; a subminiature spy camera; an early digital compact; an 8mm cine camera; a hand-cranked movie camera; a plastic toy camera; a disposable camera; a modern mirrorless camera",
  "black leatherette; chrome-plated metal; brushed aluminium; bakelite; polished wood and brass; moulded plastic; stamped steel; black paint over brass", "a round lens barrel; a leather neck strap; a viewfinder hood; a hand-wound film knob; a bellows that folds flat; a flash cube; a rotating dial for exposure; a strap lug with wear; a soft leather case; a lens cap on a cord",
  "from the 1890s; from the 1920s; from the 1950s; from the 1960s; from the 1970s; from the 1990s; from the 2000s; of a current design", ("lens ring", "top plate")),
 'typewriter': ('typewriter', "an upright office typewriter; a portable typewriter in a case; a coloured portable typewriter; an electric typewriter; a golf-ball electric typewriter; an early index typewriter; a writing-ball typewriter with keys on a dome; a toy typewriter; a stenotype machine; a braille writer; a curved-keyboard typewriter; a travel typewriter in a zip case; a folding portable typewriter",
  "black enamelled steel; painted pastel metal; chrome and bakelite; cast aluminium; plastic; wood and brass; green crackle paint", "round glass-topped keys with white lettering; a ribbon on twin spools; a carriage return lever; a sliding carriage; a bell that rings at the margin; a tab key; a paper rest; a worn rubber platen; a case with a strap",
  "from the 1880s; from the 1900s; from the 1930s; from the 1950s; from the 1960s; from the 1970s; from the 1980s", ("front plate", "carriage plate")),
 'radio': ('radio or early electronic', "a crystal radio set; a cathedral-shaped wooden radio; a bakelite tabletop radio; an Art Deco wooden console radio; a pocket transistor radio; a portable twin-speaker boombox; a shortwave receiver with a big dial; a valve amplifier; an early television set in a wooden cabinet; a reel-to-reel tape recorder; a portable cassette player; a record player in a case; a pocket calculator with red digits; a pair of walkie-talkies; an early computer terminal",
  "bakelite; polished walnut veneer; painted steel; chrome and plastic; brushed aluminium; moulded plastic; leatherette and metal", "a round tuning dial with station names; a row of piano-style knobs; a cloth speaker grille; a telescopic antenna; glowing valves visible at the back; a carrying handle; a lit dial in amber; a tangle of cable; a magic-eye tuning tube",
  "from the 1920s; from the 1930s; from the 1950s; from the 1960s; from the 1970s; from the 1980s", ("dial", "back plate")),
 'telephone': ('telephone', "a brass candlestick telephone; a wooden wall-mounted crank telephone; a rotary desk telephone; a bakelite wall telephone; a coin-operated payphone; a push-button desk telephone; a curved handset telephone with a hidden dial; an early cordless handset on a base; an answering machine with a cassette; a telephone switchboard; an army field telephone; a car telephone with a coiled cord; an intercom handset; a transparent novelty telephone",
  "black bakelite; brass; ivory plastic; coloured plastic; polished oak; enamelled steel; chrome", "a numbered dial with finger holes; a cloth-covered cord; a separate earpiece on a hook; a bell box; a coin slot; a handset cradle; a ringing bell with a hammer; a card with a number written in; a button panel; an extension cord of tangled loops",
  "from the 1900s; from the 1920s; from the 1950s; from the 1960s; from the 1970s; from the 1980s; from the 1990s", ("dial card", "base plate")),
 'music': ('musical instrument', "a violin in its case; an acoustic guitar; a brass trumpet; a piano accordion; a harmonica; a concertina; a five-string banjo; a mandolin; a wooden clarinet; a silver flute; a saxophone; a snare drum; a ukulele; a zither; a hurdy-gurdy; a melodeon; a tambourine",
  "polished spruce and maple; lacquered brass; rosewood; ebony and silver; pearl-inlaid wood; painted tin; nickel-plated metal", "inlaid pearl markers; a cracked varnish; a worn fingerboard; a mouthpiece with tooth marks; a strap worn thin; a maker's label glimpsed through a hole; a velvet-lined case; shiny worn valves; spare strings in a pouch; a dented bell",
  "from the 1700s; from the 1800s; from the 1900s; from the 1930s; from the 1960s; from the 1980s; of a current design", ("label", "headstock")),
}
def build(final=None):
    G = {'col_condition': COND, 'col_display': DISPLAY, 'col_service': SERVICE, 'col_colour': COLOUR, 'col_group': GROUP}
    allp = []
    for k, (noun, types, mats, feats, eras, mk) in C.items():
        G['col_%s_type' % k] = P(types); G['col_%s_material' % k] = P(mats); G['col_%s_feature' % k] = P(feats); G['col_%s_era' % k] = P(eras)
        G['col_%s_marks' % k] = ['with the name %s engraved on the %s' % ('__text_brand__', mk[0]), 'with %s printed on the %s' % ('__text_brand__', mk[0]), 'with %s stamped on the %s and a logo of %s' % ('__text_brand__', mk[1], '__text_logo_emblem__'), 'with %s and a model number %s on the %s' % ('__text_brand__', '"Model 41"', mk[1])]
        G['col_%s_marks_fill' % k] = ['with "MAKER NAME" engraved on the %s' % mk[0]]
        art = 'A'
        G['col_%s_look' % k] = ['__col_%s_type__, %s, in __col_colour__ with __col_%s_feature__, made with %s, %s' % (k, '__col_%s_era__' % k, k, '__col_%s_material__' % k, '__col_%s_marks__' % k)]
        G['col_%s_look_fill' % k] = ['__col_%s_type__, %s, in __col_colour__ with __col_%s_feature__, %s' % (k, '__col_%s_era__' % k, k, '__col_%s_marks_fill__' % k)]
        G['col_%s_prompt' % k] = ['A collectable %s, __col_%s_look__. It is __col_condition__, with __col_service__, and it is __col_display__.' % (noun, k)]
        G['col_%s_prompt_fill' % k] = ['A collectable %s, __col_%s_look_fill__. It is __col_condition__, with __col_service__, and it is __col_display__.' % (noun, k)]
        G['col_%s_short' % k] = ['__col_%s_type__, %s, in __col_colour__.' % (k, '__col_%s_era__' % k)]
        G['col_%s_group_prompt' % k] = ['Three %ss are shown together. The first is __col_%s_short__ The second is __col_%s_short__ The third is __col_%s_short__ They are all __col_condition__, and they are __col_display__.' % (noun, k, k, k)]
        allp.append(k)
    G['col_prompt'] = ['__col_%s_prompt__' % k for k in allp]; G['col_group_prompt'] = ['__col_%s_group_prompt__' % k for k in allp]
    G['col_short'] = ['__col_%s_short__' % k for k in allp]; G['col_prompt_fill'] = ['__col_%s_prompt_fill__' % k for k in allp]
    G['v76_coll_entry_points'] = ['col_prompt', 'col_prompt_fill', 'col_group_prompt', 'col_short'] + ['col_%s_prompt' % k for k in allp]
    return G
if __name__ == '__main__': print(len(build()))
